steps.source:
const out = {};
out.plans = q.help("plans");
out.timeline = q.help("timeline");
out.changes = q.help("changes");
out.states = q.help("states");
out

const run = a.variant("checked"); const row = run.function("row"); const middle = row.timeline("middle");
globalThis.run=run; globalThis.row=row; globalThis.middle=middle;
const hdr = q.ir.instructions().opcode("load").resultType("i32").pointer(row.argument(0)).count();
globalThis.hdr=hdr;
const hc = q.help("metrics"); const hp = q.help("params");
({hc, hp, metricExplain: q.explain(hdr)})

const changesTable = q.run(middle.measure(hdr).changes().table("ordinal","pass","before","after","delta","status"));
const first = q.run(middle.measure(hdr).changes().where(c => c.status === "known" && c.delta < 0).first());
({first, tableLen: changesTable.length, table: changesTable})

const ch = middle.measure(hdr).changes();
const negs = q.run(ch.where(c => c.delta !== null && c.delta < 0).select("ordinal","pass","before","after","delta","status"));
const gaps = q.run(ch.where(c => c.status === "gap").select("ordinal","pass","from","fromPass","before","after","status","skipped","skippedOrdinals","endpointDelta"));
const notKnown = q.run(ch.where(c => c.status !== "known" && c.status !== "first").select("ordinal","pass","status","reason"));
const m73 = q.run(hdr.at(middle.at(73).after));
const m74 = q.run(hdr.at(middle.at(74).after));
({negs, gapCount: gaps.length, gaps: gaps.slice(0,4), notKnownCount: notKnown.length, notKnown: notKnown.slice(0,6), m73: {status:m73.status, value:m73.value, unit:m73.unit, coverage:m73.coverage}, m74: {status:m74.status, value:m74.value, unit:m74.unit, coverage:m74.coverage}})

const ch = middle.measure(hdr).changes();
const negs = q.run(ch.where(c => c.delta !== null && c.delta < 0).select("ordinal","pass","before","after","delta","status"));
const gaps = q.run(ch.where(c => c.status === "gap").select("ordinal","pass","from","fromPass","before","after","skipped","skippedOrdinals","endpointDelta"));
const nk = q.run(ch.where(c => c.status !== "known" && c.status !== "first").select("ordinal","pass","status","reason"));
const m73 = q.run(hdr.at(middle.at(73).after));
const m74 = q.run(hdr.at(74).after);
({negs, gaps, nk, m73, m74})

ch = middle.measure(hdr).changes();
negs = q.run(ch.where(c => c.delta !== null && c.delta < 0).select("ordinal","pass","before","after","delta","status"));
gaps = q.run(ch.where(c => c.status === "gap").select("ordinal","pass","from","fromPass","before","after","skipped","skippedOrdinals","endpointDelta"));
nk = q.run(ch.where(c => c.status !== "known" && c.status !== "first").select("ordinal","pass","status","reason"));
m73 = q.run(hdr.at(middle.at(73).after));
m74 = q.run(hdr.at(74).after);
({negs, gaps, nk, m73, m74})

const ch2 = middle.measure(hdr).changes();
negs2 = q.run(ch2.where(c => c.delta !== null && c.delta < 0).select("ordinal","pass","before","after","delta","status"));
gaps2 = q.run(ch2.where(c => c.status === "gap").select("ordinal","pass","from","fromPass","before","after","skipped","skippedOrdinals","endpointDelta"));
nk2 = q.run(ch2.where(c => c.status !== "known" && c.status !== "first").select("ordinal","pass","status","reason"));
m73 = q.run(hdr.at(middle.at(73).after));
m74b = q.run(hdr.at(74).after);
({negs2, gaps2, nk2, m73, m74b})

const chA = middle.measure(hdr).changes();
const negsA = q.run(chA.where(c => c.delta !== null && c.delta < 0).select("ordinal","pass","before","after","delta","status"));
const gapsA = q.run(chA.where(c => c.status === "gap").select("ordinal","pass","from","fromPass","before","after","skipped","skippedOrdinals","endpointDelta"));
const nkA = q.run(chA.where(c => c.status !== "known" && c.status !== "first").select("ordinal","pass","status","reason"));
const s73 = q.run(hdr.at(middle.at(73).after));
const s74 = q.run(hdr.at(74).after);
({negsA, gapsA: {count: gapsA.count, firstTwo: gapsA.rows.slice(0,2)}, nkA, s73, s74})

const s74b = q.run(hdr.at(middle.at(74).after));
const negsB = q.run(chA.where(c => c.delta !== null && c.delta < 0).select("ordinal","pass","before","after","delta","status"));
const gapsB = q.run(chA.where(c => c.status === "gap").select("ordinal","pass","from","fromPass","before","after","skipped","skippedOrdinals","endpointDelta"));
const nkB = q.run(chA.where(c => c.status !== "known" && c.status !== "first").select("ordinal","pass","status","reason"));
({s73, s74: s74b, negsB, gapInfo: {count: gapsB.count, rows: gapsB.rows.slice(0,3)}, nkB})

const capHelp = q.help("capabilities");
const caps = q.capabilities();
const nkC = q.run(chA.where(c => c.status === "unavailable" || c.status === "unknown").select("ordinal","pass","status","reason","before","after"));
({capHelp, caps, unavailableOrUnknown: nkC})

const seq = q.run(chA.where(c => c.ordinal >= 86 && c.ordinal <= 92).select("ordinal","pass","status","reason","before","after","delta"));
const unkRows = q.run(chA.where(c => c.status === "unknown").select("ordinal","pass","reason","before","after").first());
const filtered = q.run(middle.where(e => e.pass === "EarlyCSEPass").measure(hdr).changes().table("ordinal","pass","status","reason","before","after","skippedOrdinals"));
const srcLoc = q.run(run.initialModule().sourceLocations({ function: "row" }));
({seq, unkRows, filteredCount: filtered.count, filteredRows: filtered.rows.slice(0,3), srcLoc})

const e73 = q.run(run.events("middle").at(73).select("ordinal","passId","scope","header"));
const e74 = q.run(run.events("middle").at(74).select("ordinal","passId","scope","header"));
let prof = null;
try { prof = q.run(profiles.arm("checked-gcc").region("row").workload("opening-160-rows").total("instructions")); } catch (e) { prof = {err: String(e.message).slice(0,160), arms: profiles.arms()}; }
({e73, e74, prof})
